def solve(record):
    # Extract the problem instance from the record
    data = record.get('record_1')
    if data is None:
        return None
    edges, source, target = data

    # If source and target are the same, the shortest route uses zero edges
    if source == target:
        return 0

    # Build an adjacency list for the directed graph
    from collections import defaultdict, deque
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Breadth‑first search to find the shortest number of edges
    visited = {source}
    queue = deque([(source, 0)])
    while queue:
        node, dist = queue.popleft()
        for nxt in graph.get(node, []):
            if nxt == target:
                return dist + 1
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, dist + 1))

    # Target cannot be reached from source
    return None
